/* ---------- Custom database brochure iframe ---------- */
	.custom-brochure-frame {
		width: 100%;
		min-height: 100vh;
		border: none;
		display: block;
		background: #d8dcd5;
	}

	@media print {
		.custom-brochure-frame {
			width: 100% !important;
			height: 100% !important;
			border: none !important;
			position: fixed !important;
			inset: 0 !important;
			z-index: 99999 !important;
			background: #ffffff !important;
		}
	}

	/* ---------- Floating toolbar (screen only) ---------- */
	.brochure-toolbar {
		position: fixed;
		top: 16px;
		right: 16px;
		z-index: 900;
		display: flex;
		gap: 8px;
	}

	.tool-btn {
		background: #ffffff;
		color: #2f6f2f;
		border: 1px solid #c7d8b9;
		border-radius: 999px;
		padding: 10px 18px;
		font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
		font-size: 13px;
		font-weight: 700;
		cursor: pointer;
		box-shadow: 0 6px 18px rgba(31, 41, 51, 0.18);
	}

	.tool-btn.primary {
		background: linear-gradient(135deg, #2f6f2f 0%, #78be20 100%);
		color: #fff;
		border-color: transparent;
	}

	.tool-btn:hover {
		filter: brightness(1.04);
	}

	.tool-btn:disabled {
		opacity: 0.6;
		cursor: not-allowed;
	}

	.toolbar-badge {
		font-size: 10px;
		font-weight: 700;
		letter-spacing: 0.4px;
		text-transform: uppercase;
		color: #2f6f2f;
		background: #e7f3da;
		border-radius: 999px;
		padding: 2px 7px;
	}

	/* ---------- Email editor modal (screen only) ---------- */
	.email-modal-backdrop {
		position: fixed;
		inset: 0;
		background: rgba(15, 23, 31, 0.45);
		z-index: 998;
	}

	.email-modal {
		position: fixed;
		top: 50%;
		left: 50%;
		transform: translate(-50%, -50%);
		width: 460px;
		max-width: 90vw;
		background: #ffffff;
		border-radius: 16px;
		box-shadow: 0 16px 40px rgba(0, 0, 0, 0.24);
		z-index: 999;
		overflow: hidden;
		font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
		color: #11181f;
		animation: modalFadeIn 0.18s ease-out;
	}

	@keyframes modalFadeIn {
		from {
			opacity: 0;
			transform: translate(-50%, -47%) scale(0.97);
		}
		to {
			opacity: 1;
			transform: translate(-50%, -50%) scale(1);
		}
	}

	.email-modal-header {
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding: 16px 20px;
		background: linear-gradient(135deg, #2f6f2f 0%, #78be20 100%);
		color: #fff;
	}

	.email-modal-header h3 {
		margin: 0;
		font-size: 16px;
		font-weight: 800;
	}

	.email-modal-close {
		background: rgba(255, 255, 255, 0.18);
		border: none;
		color: #fff;
		font-size: 20px;
		line-height: 1;
		width: 28px;
		height: 28px;
		border-radius: 6px;
		cursor: pointer;
		display: flex;
		align-items: center;
		justify-content: center;
	}

	.email-modal-close:hover {
		background: rgba(255, 255, 255, 0.32);
	}

	.email-modal-body {
		padding: 20px;
		display: flex;
		flex-direction: column;
		gap: 12px;
	}

	.email-modal-body label {
		font-size: 13px;
		font-weight: 700;
		color: #1f2933;
	}

	.email-input-wrapper {
		display: flex;
		flex-direction: column;
		gap: 8px;
	}

	.email-input-field {
		width: 100%;
		font-size: 14px;
		padding: 10px 12px;
		border: 1.5px solid #d6ddd2;
		border-radius: 8px;
		color: #1f2933;
		box-sizing: border-box;
		transition: border-color 0.15s;
	}

	.email-input-field:focus {
		outline: none;
		border-color: #78be20;
		box-shadow: 0 0 0 3px rgba(120, 190, 32, 0.15);
	}

	.email-modal-hint {
		margin: 0;
		font-size: 12px;
		color: #6b7680;
		line-height: 1.45;
	}

	.email-modal-hint code {
		background: #f0f4ec;
		padding: 2px 6px;
		border-radius: 4px;
		font-family: monospace;
		font-size: 11px;
		color: #2f6f2f;
	}

	.email-modal-footer {
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding: 14px 20px;
		background: #f8faf6;
		border-top: 1px solid #eef2eb;
	}

	.btn-primary {
		background: linear-gradient(135deg, #2f6f2f 0%, #78be20 100%);
		border: none;
		color: #fff;
		border-radius: 8px;
		padding: 8px 18px;
		font-size: 13px;
		font-weight: 700;
		cursor: pointer;
		box-shadow: 0 2px 6px rgba(47, 111, 47, 0.25);
	}

	.btn-primary:hover {
		filter: brightness(1.05);
	}

	.btn-reset-text {
		background: none;
		border: none;
		color: #b91c1c;
		font-size: 12px;
		font-weight: 600;
		cursor: pointer;
		padding: 4px 6px;
		text-decoration: underline;
	}

	.btn-reset-text:hover {
		color: #991b1b;
	}

	.clickable-email,
	.clickable-contact {
		cursor: pointer;
		transition: color 0.15s;
	}

	@media screen {
		.clickable-email:hover,
		.clickable-contact:hover {
			color: #5ea015;
			text-decoration: underline;
			text-underline-offset: 2px;
		}
	}

	@media print {
		.brochure-toolbar,
		.email-modal-backdrop,
		.email-modal {
			display: none !important;
		}
	}

	/* =====================================================
   RapidClean Illawarra · Preventative Maintenance Brochure
   ===================================================== */

	/* ---------- Design Tokens ---------- */
	.brochure {
		--rapid-green: #78be20;
		--rapid-green-dark: #5ea015;
		--deep-green: #2f6f2f;
		--deep-green-soft: #3d8a3d;
		--dark: #1f2933;
		--ink: #11181f;
		--muted: #5f6b76;
		--light: #f4f8f1;
		--cream: #fbfcf8;
		--white: #ffffff;
		--border: #dfe8d8;
		--border-strong: #c7d8b9;

		/* Page geometry */
		--page-w: 210mm;
		--page-h: 297mm;
		--gutter: 18mm;

		font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
		color: var(--ink);
		background: #d8dcd5;
		line-height: 1.5;
		-webkit-font-smoothing: antialiased;
		padding: 1px 0;
		min-height: 100%;
	}

	.brochure * {
		box-sizing: border-box;
	}

	.brochure img {
		max-width: 100%;
	}

	/* ---------- Page Frame ---------- */
	.page {
		width: var(--page-w);
		height: var(--page-h);
		margin: 18px auto;
		background: var(--white);
		position: relative;
		overflow: hidden;
		box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
		page-break-after: always;
	}

	.page-inner {
		padding: 32mm var(--gutter) 22mm;
		position: relative;
		z-index: 2;
		height: 100%;
		display: flex;
		flex-direction: column;
	}

	/* ---------- Brand Bar ---------- */
	.brand-bar {
		position: absolute;
		top: 0;
		left: 0;
		width: 100%;
		height: 24mm;
		padding: 4mm var(--gutter);
		background: linear-gradient(180deg, #111 0%, #1a1a1a 100%);
		display: flex;
		align-items: center;
		justify-content: space-between;
		box-sizing: border-box;
		z-index: 3;
	}

	.brand-bar::after {
		content: '';
		position: absolute;
		left: 0;
		right: 0;
		bottom: 0;
		height: 1.2mm;
		background: linear-gradient(90deg, var(--rapid-green) 0%, var(--deep-green) 100%);
	}

	.site-logo {
		max-height: 16mm;
		width: auto;
		object-fit: contain;
		display: block;
	}

	.brand-tag {
		color: rgba(255, 255, 255, 0.72);
		font-size: 8.5pt;
		letter-spacing: 0.4pt;
		font-weight: 600;
	}

	/* ---------- Footer Bar ---------- */
	.footer-bar {
		position: absolute;
		bottom: 0;
		left: 0;
		width: 100%;
		height: 14mm;
		padding: 0 var(--gutter);
		background: var(--ink);
		color: var(--white);
		font-size: 9pt;
		display: flex;
		justify-content: space-between;
		align-items: center;
		gap: 12px;
		z-index: 3;
	}

	.footer-bar::before {
		content: '';
		position: absolute;
		left: 0;
		right: 0;
		top: 0;
		height: 0.8mm;
		background: linear-gradient(90deg, var(--deep-green) 0%, var(--rapid-green) 100%);
	}

	.footer-bar .footer-meta {
		display: inline-flex;
		align-items: center;
		gap: 2mm;
		color: rgba(255, 255, 255, 0.55);
		font-size: 8.5pt;
		letter-spacing: 0.3pt;
		white-space: nowrap;
	}

	.footer-bar .footer-meta strong {
		color: var(--rapid-green);
		font-weight: 700;
	}

	/* ---------- Typography ---------- */
	.brochure h1 {
		font-size: 36pt;
		line-height: 1.02;
		letter-spacing: -0.5pt;
		margin: 0 0 5mm;
		color: var(--deep-green);
		font-weight: 800;
	}

	.brochure h2 {
		font-size: 24pt;
		line-height: 1.1;
		letter-spacing: -0.3pt;
		margin: 0 0 5mm;
		color: var(--deep-green);
		font-weight: 800;
	}

	.brochure h3 {
		font-size: 13pt;
		margin: 6mm 0 2mm;
		color: var(--deep-green);
		font-weight: 700;
		letter-spacing: 0.1pt;
	}

	.brochure p {
		font-size: 10.5pt;
		margin: 0 0 4mm;
		color: var(--dark);
	}

	.brochure ul {
		margin: 2mm 0 5mm 0;
		padding-left: 5mm;
		list-style: none;
	}

	.brochure li {
		font-size: 10.3pt;
		margin-bottom: 2.2mm;
		padding-left: 5mm;
		position: relative;
		color: var(--dark);
	}

	.brochure li::before {
		content: '';
		position: absolute;
		left: 0;
		top: 2.4mm;
		width: 2.2mm;
		height: 2.2mm;
		border-radius: 50%;
		background: var(--rapid-green);
	}

	.bullet-grid-2 {
		display: grid;
		grid-template-columns: 1fr 1fr;
		grid-template-rows: repeat(3, auto);
		gap: 2.2mm 8mm;
		padding-left: 0;
	}

	.bullet-grid-2 li {
		margin-bottom: 0;
	}

	.subtitle {
		font-size: 14pt;
		line-height: 1.4;
		color: var(--muted);
		max-width: 155mm;
		margin: 0 0 8mm;
		font-weight: 400;
	}

	/* ---------- Page 3 · Full-width approach image ---------- */
	.page-approach .page-inner {
		padding-bottom: 18mm;
	}

	.page-approach h2 {
		margin-bottom: 2.5mm;
		font-size: 20pt;
	}

	.page-approach .page-inner > p {
		margin-bottom: 2mm;
		font-size: 10pt;
	}

	.page-approach .approach-visual {
		position: relative;
		margin: 1mm calc(-1 * var(--gutter)) 2.5mm;
		width: calc(100% + 2 * var(--gutter));
		line-height: 0;
		background: var(--white);
	}

	.page-approach .approach-visual img {
		width: 100%;
		height: auto;
		display: block;
		object-fit: contain;
	}

	.page-approach .process-grid {
		gap: 2mm;
		margin-top: 0;
	}

	.page-approach .process-grid .step {
		display: block;
		padding: 2.5mm 3mm;
	}

	.page-approach .process-grid .step::before {
		display: none;
		content: none;
	}

	.page-approach .process-grid .step h3 {
		font-size: 9.5pt;
		margin: 0 0 0.8mm;
	}

	.page-approach .process-grid .step p {
		font-size: 8pt;
		line-height: 1.3;
	}

	/* ---------- Page 1 · Full-width bottom image ---------- */
	.page-intro .page-inner {
		padding-bottom: 124mm;
	}

	.page-intro .page-inner ul {
		margin-bottom: 6mm;
	}

	.page-full-image {
		position: absolute;
		left: 0;
		bottom: 14mm;
		width: 100%;
		margin: 0;
		z-index: 2;
		line-height: 0;
		padding-top: 5mm;
		background: var(--white);
	}

	.page-full-image img {
		width: 100%;
		height: auto;
		display: block;
	}

	/* ---------- Page 2 · Challenge full-width visual ---------- */
	.page-challenge .page-inner {
		padding-bottom: 18mm;
	}

	.page-challenge h2 {
		margin-bottom: 3mm;
	}

	.page-challenge .page-inner > p {
		margin-bottom: 3mm;
	}

	.page-challenge h3 {
		margin: 3mm 0 1.5mm;
	}

	.page-challenge .bullet-grid-2 {
		margin: 0 0 4mm;
		gap: 1.6mm 8mm;
	}

	.page-challenge .bullet-grid-2 li {
		font-size: 9.8pt;
	}

	.page-challenge .callout {
		margin: 4mm 0;
		padding: 4.5mm 6mm;
	}

	.page-challenge .callout h3 {
		margin: 0 0 1.5mm;
	}

	.page-challenge .page-inner > h3:last-of-type {
		margin-top: 3mm;
	}

	.page-challenge .page-inner > p:last-child {
		margin-bottom: 0;
		font-size: 10pt;
	}

	/* ---------- Callout ---------- */
	.callout {
		background: linear-gradient(135deg, #f7fbf3 0%, #eef5e6 100%);
		border-left: 5px solid var(--rapid-green);
		padding: 6mm 7mm;
		border-radius: 12px;
		margin: 3mm 0;
		box-shadow: 0 2px 8px rgba(47, 111, 47, 0.05);
	}

	.callout h3 {
		margin: 0 0 2mm;
		font-size: 12.5pt;
	}

	.callout p {
		margin: 0;
		font-size: 10.2pt;
	}

	/* ---------- Grids ---------- */
	.grid-3 {
		display: grid;
		grid-template-columns: repeat(3, 1fr);
		gap: 4mm;
	}

	/* ---------- Tile ---------- */
	.tile {
		background: var(--cream);
		border: 1px solid var(--border);
		border-radius: 12px;
		padding: 5mm;
		min-height: 36mm;
		position: relative;
		font-size: 9.8pt;
		line-height: 1.45;
		color: var(--dark);
	}

	.tile::before {
		content: '';
		position: absolute;
		top: 0;
		left: 5mm;
		width: 10mm;
		height: 1mm;
		background: var(--rapid-green);
		border-radius: 0 0 1mm 1mm;
	}

	.tile strong {
		color: var(--deep-green);
		display: block;
		margin-bottom: 2mm;
		font-size: 10.8pt;
		font-weight: 700;
	}

	/* ---------- Logo Grid ---------- */
	.logo-grid {
		display: grid;
		grid-template-columns: repeat(6, 1fr);
		gap: 2mm 3mm;
		margin: 2mm 0 3mm;
	}

	.logo-tile {
		display: flex;
		flex-direction: column;
		align-items: center;
		justify-content: center;
		gap: 1mm;
		text-align: center;
	}

	.logo-tile img {
		max-width: 28mm;
		max-height: 10mm;
		object-fit: contain;
		filter: saturate(0.95);
	}

	.logo-tile span {
		font-size: 6.8pt;
		color: var(--muted);
		font-weight: 700;
		letter-spacing: 0.1pt;
		line-height: 1.2;
	}

	/* ---------- Process / Steps ---------- */
	.process {
		counter-reset: step;
		display: grid;
		gap: 3mm;
	}

	.process-grid {
		counter-reset: step;
		display: grid;
		grid-template-columns: repeat(3, 1fr);
		gap: 3mm;
		margin-top: 4mm;
	}

	.process-grid .step {
		grid-template-columns: 1fr;
		gap: 2mm;
		padding: 3.5mm;
	}

	.process-grid .step::before {
		width: 9mm;
		height: 9mm;
		font-size: 8.5pt;
	}

	.process-grid .step h3 {
		font-size: 10pt;
	}

	.process-grid .step p {
		font-size: 8.8pt;
		line-height: 1.35;
	}

	.step {
		display: grid;
		grid-template-columns: 11mm 1fr;
		gap: 4mm;
		align-items: start;
		padding: 4mm 4mm 4mm 3mm;
		border: 1px solid var(--border);
		border-radius: 10px;
		background: var(--white);
		box-shadow: 0 1px 3px rgba(31, 41, 51, 0.04);
	}

	.step::before {
		counter-increment: step;
		content: counter(step, decimal-leading-zero);
		width: 11mm;
		height: 11mm;
		border-radius: 50%;
		background: linear-gradient(135deg, var(--rapid-green) 0%, var(--deep-green) 100%);
		color: white;
		display: flex;
		align-items: center;
		justify-content: center;
		font-weight: 800;
		font-size: 10pt;
		letter-spacing: 0.3pt;
		box-shadow: 0 2px 6px rgba(47, 111, 47, 0.25);
	}

	.step h3 {
		margin: 0 0 1mm;
		font-size: 11.5pt;
	}

	.step p {
		margin: 0;
		font-size: 9.6pt;
		color: var(--dark);
		line-height: 1.4;
	}

	/* ---------- Page 5 · Next Steps ---------- */
	.page-next .next-hero {
		position: absolute;
		top: 24mm;
		right: 0;
		bottom: 14mm;
		width: 55%;
		z-index: 1;
		background-color: #e8efe4;
		background-size: cover;
		background-position: center right;
		background-repeat: no-repeat;
		display: flex;
		align-items: center;
		justify-content: center;
	}

	.page-next .next-hero::after {
		content: '';
		position: absolute;
		inset: 0;
		background: linear-gradient(
			90deg,
			rgba(255, 255, 255, 1) 0%,
			rgba(255, 255, 255, 0.55) 8%,
			rgba(255, 255, 255, 0.15) 18%,
			transparent 28%
		);
		pointer-events: none;
	}

	.page-next .next-hero.has-image {
		background-color: transparent;
	}

	.page-next .next-hero-placeholder {
		position: relative;
		z-index: 1;
		color: rgba(47, 111, 47, 0.45);
		font-size: 11pt;
		font-weight: 600;
		letter-spacing: 0.4pt;
	}

	.page-next .next-inner {
		padding-bottom: 18mm;
		z-index: 2;
	}

	.page-next .next-content {
		max-width: 100mm;
		position: relative;
		z-index: 2;
	}

	.page-next .next-headline {
		margin: 0 0 4mm;
		font-size: 28pt;
		line-height: 1.05;
		letter-spacing: -0.4pt;
		font-weight: 800;
		display: flex;
		flex-direction: column;
		gap: 0;
	}

	.page-next .next-headline-dark {
		color: var(--ink);
	}

	.page-next .next-headline-green {
		color: var(--deep-green);
	}

	.page-next .next-headline::after {
		content: '';
		display: block;
		width: 14mm;
		height: 1.2mm;
		margin-top: 3.5mm;
		background: var(--rapid-green);
		border-radius: 1mm;
	}

	.page-next .next-lead {
		max-width: 95mm;
		font-size: 10.5pt;
		line-height: 1.45;
		margin: 0 0 6mm;
		color: var(--dark);
	}

	.page-next .next-benefits {
		list-style: none;
		margin: 0;
		padding: 0;
		display: flex;
		flex-direction: column;
		gap: 4.5mm;
	}

	.page-next .next-benefits li {
		display: flex;
		align-items: flex-start;
		gap: 3.5mm;
		padding-left: 0;
		margin: 0;
	}

	.page-next .next-benefits li::before {
		display: none;
	}

	.page-next .next-benefit-icon {
		flex-shrink: 0;
		width: 10.5mm;
		height: 10.5mm;
		border-radius: 50%;
		background: linear-gradient(135deg, var(--rapid-green) 0%, var(--deep-green) 100%);
		color: white;
		display: flex;
		align-items: center;
		justify-content: center;
		box-shadow: 0 2px 6px rgba(47, 111, 47, 0.22);
	}

	.page-next .next-benefit-icon svg {
		width: 5.2mm;
		height: 5.2mm;
	}

	.page-next .next-benefits strong {
		display: block;
		font-size: 11.5pt;
		color: var(--ink);
		font-weight: 700;
		margin-bottom: 0.6mm;
		line-height: 1.2;
	}

	.page-next .next-benefits li span:not(.next-benefit-icon) {
		display: block;
		font-size: 9.8pt;
		color: var(--dark);
		line-height: 1.35;
	}

	.page-next .next-cta-card {
		margin-top: auto;
		position: relative;
		z-index: 2;
		background: linear-gradient(135deg, var(--deep-green) 0%, var(--rapid-green) 100%);
		color: white;
		border-radius: 14px;
		padding: 5.5mm 6mm 5mm;
		box-shadow: 0 4px 14px rgba(47, 111, 47, 0.22);
	}

	.page-next .next-cta-contacts {
		display: grid;
		grid-template-columns: 0.85fr 1.5fr 0.95fr;
		gap: 0;
	}

	.page-next .next-cta-item {
		display: flex;
		align-items: flex-start;
		gap: 2.5mm;
		padding: 0 3.5mm;
		min-width: 0;
	}

	.page-next .next-cta-item:first-child {
		padding-left: 1mm;
	}

	.page-next .next-cta-item:not(:first-child) {
		border-left: 0.5px solid rgba(255, 255, 255, 0.35);
	}

	.page-next .next-cta-item:nth-child(2) .value {
		white-space: nowrap;
		font-size: 8.8pt;
	}

	.page-next .next-cta-icon {
		flex-shrink: 0;
		width: 5mm;
		height: 5mm;
		margin-top: 0.5mm;
		color: rgba(255, 255, 255, 0.95);
	}

	.page-next .next-cta-icon svg {
		width: 100%;
		height: 100%;
		display: block;
	}

	.page-next .next-cta-item .label {
		display: block;
		font-size: 7.5pt;
		letter-spacing: 1.4pt;
		text-transform: uppercase;
		opacity: 0.8;
		font-weight: 600;
		margin-bottom: 0.8mm;
	}

	.page-next .next-cta-item .value {
		display: block;
		font-size: 9.5pt;
		font-weight: 700;
		line-height: 1.25;
		word-break: break-word;
		color: white;
	}

	.page-next .next-cta-tagline {
		margin: 4mm 0 0;
		padding: 3.5mm 0 0 3.5mm;
		border-top: 0.5px solid rgba(255, 255, 255, 0.35);
		position: relative;
		font-size: 9.8pt;
		line-height: 1.4;
		color: white;
	}

	.page-next .next-cta-tagline::before {
		content: '';
		position: absolute;
		left: 0;
		top: 3.5mm;
		bottom: 0;
		width: 1.2mm;
		background: white;
		border-radius: 1mm;
	}

	/* ---------- Section Header ---------- */
	.section-num {
		display: inline-flex;
		align-items: center;
		gap: 3mm;
		color: var(--rapid-green-dark);
		font-size: 9pt;
		letter-spacing: 2.5pt;
		text-transform: uppercase;
		font-weight: 700;
		margin-bottom: 4mm;
	}

	.section-num :global(.section-badge) {
		width: 9mm;
		height: 9mm;
		flex-shrink: 0;
		display: inline-block;
		vertical-align: middle;
	}

	.section-num span {
		display: inline-flex;
		width: 9mm;
		height: 9mm;
		border: 1.4pt solid var(--rapid-green);
		border-radius: 50%;
		align-items: center;
		justify-content: center;
		font-size: 9.5pt;
		letter-spacing: 0;
		line-height: 1;
		padding: 0;
		margin: 0;
		box-sizing: border-box;
		flex-shrink: 0;
		color: var(--rapid-green-dark);
	}

	/* Watermark accent in page corners */
	.corner-accent {
		position: absolute;
		bottom: 22mm;
		right: 0;
		width: 12mm;
		height: 60mm;
		background: linear-gradient(180deg, transparent, var(--rapid-green) 50%, transparent);
		opacity: 0.08;
		z-index: 1;
		pointer-events: none;
	}

	/* =====================================================
   FRONT COVER
   ===================================================== */
	.cover-page {
		background: #0e1614;
		color: white;
	}

	.cover-hero {
		position: absolute;
		inset: 0;
		background-size: cover;
		background-position: center;
		z-index: 0;
	}

	.cover-hero::after {
		content: '';
		position: absolute;
		inset: 0;
		background:
			linear-gradient(
				180deg,
				rgba(8, 18, 12, 0.55) 0%,
				rgba(8, 18, 12, 0.45) 35%,
				rgba(8, 22, 14, 0.96) 100%
			),
			linear-gradient(90deg, rgba(47, 111, 47, 0.35) 0%, rgba(0, 0, 0, 0) 60%);
	}

	.cover-content {
		position: relative;
		z-index: 2;
		height: 100%;
		padding: 22mm 22mm 22mm;
		display: flex;
		flex-direction: column;
		justify-content: space-between;
		color: white;
	}

	.cover-top {
		display: flex;
		justify-content: space-between;
		align-items: flex-start;
		gap: 8mm;
	}

	.cover-top .logo {
		max-height: 18mm;
		width: auto;
		object-fit: contain;
	}

	.cover-top .tag {
		text-align: right;
		font-size: 8.5pt;
		letter-spacing: 1.5pt;
		text-transform: uppercase;
		color: rgba(255, 255, 255, 0.75);
		font-weight: 600;
		line-height: 1.5;
	}

	.cover-body {
		margin-top: auto;
		margin-bottom: 14mm;
		max-width: 170mm;
	}

	.cover-body .eyebrow-light {
		display: inline-flex;
		align-items: center;
		gap: 4mm;
		color: var(--rapid-green);
		letter-spacing: 3pt;
		font-size: 9.5pt;
		text-transform: uppercase;
		font-weight: 700;
		margin-bottom: 8mm;
	}

	.cover-body .eyebrow-light::before {
		content: '';
		display: inline-block;
		width: 14mm;
		height: 1.4mm;
		background: var(--rapid-green);
		border-radius: 1mm;
	}

	.cover-body h1 {
		color: white;
		font-size: 52pt;
		line-height: 0.98;
		margin: 0 0 8mm;
		letter-spacing: -1pt;
		font-weight: 800;
	}

	.cover-body .lead {
		color: rgba(255, 255, 255, 0.88);
		font-size: 13pt;
		line-height: 1.5;
		max-width: 155mm;
		margin: 0;
		font-weight: 400;
	}

	.cover-meta {
		border-top: 1px solid rgba(255, 255, 255, 0.2);
		padding-top: 8mm;
		display: grid;
		grid-template-columns: 1fr 1fr 1fr;
		gap: 12mm;
	}

	.cover-meta .item .label {
		display: block;
		font-size: 8pt;
		letter-spacing: 1.8pt;
		text-transform: uppercase;
		color: rgba(255, 255, 255, 0.6);
		font-weight: 600;
		margin-bottom: 2mm;
	}

	.cover-meta .item .value {
		display: block;
		font-size: 11.5pt;
		font-weight: 700;
		color: white;
		line-height: 1.3;
	}

	/* =====================================================
   BACK COVER
   ===================================================== */
	.back-cover-page {
		background: linear-gradient(180deg, #0c1a13 0%, #112a1b 50%, #0a1410 100%);
		color: white;
	}

	.back-cover-hero {
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		height: 110mm;
		background-size: cover;
		background-position: center;
		opacity: 0.28;
		z-index: 0;
	}

	.back-cover-hero::after {
		content: '';
		position: absolute;
		inset: 0;
		background: linear-gradient(180deg, rgba(12, 26, 19, 0.35) 0%, rgba(12, 26, 19, 1) 92%);
	}

	.back-cover-inner {
		position: relative;
		z-index: 2;
		height: 100%;
		padding: 26mm 22mm 22mm;
		display: flex;
		flex-direction: column;
	}

	.back-cover-top {
		display: flex;
		justify-content: space-between;
		align-items: flex-start;
		gap: 8mm;
	}

	.back-cover-top .logo {
		max-height: 16mm;
		width: auto;
		object-fit: contain;
	}

	.back-cover-top .ribbon {
		text-align: right;
		font-size: 8.5pt;
		letter-spacing: 2pt;
		text-transform: uppercase;
		color: var(--rapid-green);
		font-weight: 700;
	}

	.back-cover-statement {
		font-size: 24pt;
		line-height: 1.2;
		font-weight: 600;
		color: rgba(255, 255, 255, 0.96);
		max-width: 155mm;
		margin: 28mm 0 0;
		letter-spacing: -0.3pt;
		position: relative;
	}

	.back-cover-statement::before {
		content: '\201C';
		display: block;
		color: var(--rapid-green);
		font-size: 60pt;
		line-height: 0;
		margin-bottom: 14mm;
		font-family: Georgia, 'Times New Roman', serif;
	}

	.back-cover-statement cite {
		display: block;
		margin-top: 6mm;
		font-size: 10pt;
		letter-spacing: 2pt;
		text-transform: uppercase;
		color: rgba(255, 255, 255, 0.6);
		font-style: normal;
		font-weight: 600;
	}

	.back-cover-contact-grid {
		display: grid;
		grid-template-columns: repeat(2, 1fr);
		gap: 9mm 14mm;
		border-top: 1px solid rgba(255, 255, 255, 0.15);
		border-bottom: 1px solid rgba(255, 255, 255, 0.15);
		padding: 10mm 0;
		margin-top: auto;
	}

	.contact-card h4 {
		font-size: 8.5pt;
		letter-spacing: 2.2pt;
		text-transform: uppercase;
		color: var(--rapid-green);
		margin: 0 0 3mm;
		font-weight: 700;
	}

	.contact-card p {
		color: white;
		font-size: 12pt;
		line-height: 1.4;
		font-weight: 600;
		margin: 0;
	}

	.back-cover-footer {
		display: flex;
		justify-content: space-between;
		align-items: center;
		gap: 6mm;
		margin-top: 6mm;
		font-size: 8.5pt;
		color: rgba(255, 255, 255, 0.55);
		letter-spacing: 0.5pt;
	}

	.back-cover-footer strong {
		color: var(--rapid-green);
		font-weight: 700;
	}

	/* =====================================================
   PRINT
   ===================================================== */
	@page {
		size: A4 portrait;
		margin: 0;
	}

	@media print {
		:global(body),
		:global(html) {
			background: #ffffff !important;
			color: #11181f !important;
			margin: 0 !important;
			padding: 0 !important;
			-webkit-print-color-adjust: exact !important;
			print-color-adjust: exact !important;
		}

		.brochure-toolbar,
		.email-modal-backdrop,
		.email-modal {
			display: none !important;
		}

		.brochure {
			background: #ffffff !important;
			padding: 0 !important;
			margin: 0 !important;
			width: 210mm !important;
			-webkit-print-color-adjust: exact !important;
			print-color-adjust: exact !important;
		}

		.brochure * {
			-webkit-print-color-adjust: exact !important;
			print-color-adjust: exact !important;
		}

		.page {
			margin: 0 !important;
			box-shadow: none !important;
			width: 210mm !important;
			height: 297mm !important;
			max-height: 297mm !important;
			min-height: 297mm !important;
			page-break-inside: avoid !important;
			break-inside: avoid !important;
			page-break-after: always !important;
			break-after: page !important;
			overflow: hidden !important;
			box-sizing: border-box !important;
		}

		.page:last-child,
		.page.back-cover-page {
			page-break-after: auto !important;
			break-after: auto !important;
		}
	}
